cases.bad:
interface SerializedDraft {
  fields: { targetWord, sentence, sentenceTranslation, definitions, note, moreExample };
  noteType: string; deck: string; fieldMapping: unknown;
  tags: string[]; mediaUpdateMode: string; savedAt: number;
}
// deserializeDraft restores text fields → loadData uses rf?.targetWord ?? '' → old content returns

cases.good:
interface SerializedDraft {
  noteType: string; deck: string; fieldMapping: unknown;
  tags: string[]; mediaUpdateMode: string; savedAt: number;
  // no `fields` — text content is work product tied to a specific card, cleared on close
}
// deserializeDraft returns text fields = '' and media = []
// loadData: only restore tags + config (noteType/deck/mapping/mode); sentence always from current cue

cases.bad:
const loadData = (rf?: SerializedDraft) => ({
  targetWord: rf?.fields?.targetWord ?? '',
  definitions: rf?.fields?.definitions ?? '',
  note: rf?.fields?.note ?? '',
  moreExample: rf?.fields?.moreExample ?? '',
  tags: rf?.tags ?? [],
});

cases.good:
const loadData = (rf?: SerializedDraft) => ({
  targetWord: '',          // content — always fresh
  definitions: '',
  note: '',
  moreExample: '',
  tags: rf?.tags ?? [],    // selection — persisted, retry-friendly
  noteType: rf?.noteType ?? defaultNoteType,
  deck: rf?.deck ?? defaultDeck,
});
